async function api(route,{method='GET',body,key,raw=false}={}) {
  if(state.demo)return demoRequest(route,{method,body});
  let response;
  try {response=await fetch(route,{method,credentials:'same-origin',headers:{...(body!==undefined?{'Content-Type':raw?'application/octet-stream':'application/json'}:{}),'X-Hudson-UI':'1',...(key?{'Idempotency-Key':key}:{})},body:body===undefined?undefined:raw?body:JSON.stringify(body),signal:AbortSignal.timeout(raw||route.endsWith('/dispatch')?120000:20000)});}
  catch {throw new Error(uiText('No pudimos confirmar la respuesta de Hudson. Revisa el estado antes de repetir la acción.'));}
  const result=await response.json();if(!response.ok){const e=new Error(translateMessage(result.message)||uiText('No se pudo completar la acción.'));e.code=result.error;e.status=response.status;throw e;}return result;
}
async function refresh({render=true}={}) {
  if(state.polling)return;state.polling=true;
  try{state.data=await api('/api/dashboard');state.connected=true;ipad.sync();if(render&&!dialog.open&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){renderPage();reviewStudioFile();}}
  catch(error){state.connected=false;ipad.sync();if(error.status===401&&!dialog.open){state.data=null;setTimeout(()=>authenticate(),0);return;}if(render&&!dialog.open)renderPage();}
  finally{state.polling=false;}
}
