  const label=ht`Ver placa ${index} · ${name}`,image=ht`<img class="plate-preview-image" src="${url}" width="512" height="512" alt="Vista previa de ${esc(name)}, placa ${index}" loading="${large?'eager':'lazy'}" decoding="async"><span class="plate-preview-message" aria-hidden="true">Cargando vista previa…</span>`;
